SQL_STMT_U.val:
SELECT t.sales_date, t.customer_id, CASE WHEN t.customer_id IS NULL THEN '【売 上 日 計】' ELSE MAX(t.customer_name) END AS customer_name, SUM(COALESCE(t.standard_sales_amount, 0) + COALESCE(t.reduced_sales_amount, 0)) AS sales_amount, SUM(COALESCE(t.consumption_tax, 0)) AS consumption_tax FROM ( SELECT s.sales_date, s.customer_id, c.name AS customer_name, s.standard_sales_amount, s.reduced_sales_amount,
CASE WHEN c.tax_category = 2 THEN 0 ELSE COALESCE(s.standard_tax, 0) + COALESCE(s.reduced_tax, 0) END AS consumption_tax
FROM sale AS s LEFT JOIN customer AS c ON c.id = s.customer_id WHERE s.sales_date BETWEEN ':1' AND ':2' ) AS t GROUP BY t.sales_date, t.customer_id WITH ROLLUP HAVING t.sales_date IS NOT NULL ORDER BY t.sales_date, t.customer_id IS NULL, t.customer_id;
